using System;using System.Globalization;using System.Linq;class Program {static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){string s=line=="null"?null:line=="-"?"":new string(Enumerable.Range(0,line.Length/4).Select(i=>(char)Convert.ToUInt16(line.Substring(i*4,4),16)).ToArray());try{Console.WriteLine(s.StartsWith("Include-")?"1":"0");}catch(Exception e){Console.WriteLine(e.GetType().FullName+":"+unchecked((uint)e.HResult)+":"+e.Message);}}}}
